// GENERATED by scripts/sync-shared.ts from shared/glyphs.ts. Edit shared/, not this copy.
// The single glyph table (conventions s6). Terminal only: the desktop never uses emoji.
// No spec invents a glyph; add here first.

export const GLYPH = {
  carrot: '🥕', // Carrot / burn
  pom: '🍅', // Pom / focus / cache
  cold: '💤', // cold or asleep
  hot: '🔥',
  plenty: '🧊',
  ok: '✅',
  warn: '⚠',
  denied: '⛔',
  protected: '🔒',
  branch: '🌿',
  pr: '🔀',
  tests: '🧪',
  coverage: '📈',
  port: '🔌',
  checkpoint: '📸',
  pets: '🐾',
  queue: '📥',
  plan: '📋',
  // pet costumes
  detective: '🔍',
  scientist: '🧪',
  planner: '📋',
  scribe: '🪶',
  builder: '🔧',
  plain: '🐾',
  // phase markers and bullets (plain symbols)
  bullet: '▪',
  bulletEmpty: '▫',
  play: '▶',
  timer: '⏱',
  edit: '📝',
} as const

export type GlyphName = keyof typeof GLYPH

export const METER_FULL = '█'
export const METER_EMPTY = '░'
export const SEP = '·'
export const GROUP_SEP = '│'
export const METER_CELLS = 12

export const glyph = (name: GlyphName): string => GLYPH[name]

/** Text meter: `███████░░░░░`. `filled` is clamped to 0..cells. */
export function termMeter(filled: number, cells = METER_CELLS): string {
  const f = Math.max(0, Math.min(cells, Math.round(filled)))
  return METER_FULL.repeat(f) + METER_EMPTY.repeat(cells - f)
}

/** Meter from a 0..1 ratio. */
export const termMeterRatio = (ratio: number, cells = METER_CELLS): string =>
  termMeter(Math.round(Math.max(0, Math.min(1, ratio)) * cells), cells)

/** True when any surface is the desktop app (then toasts carry no emoji). */
export const hasDesktop = (surfaces: readonly string[]): boolean => surfaces.some(s => s === 'desktop')

/**
 * Toast prefix (conventions s6): the emoji plus a space, only when no surface is `desktop`;
 * otherwise ''. `$.session.surfaces()` supplies the list (T:2816).
 */
export const toastGlyph = (surfaces: readonly string[], name: GlyphName = 'warn'): string =>
  hasDesktop(surfaces) ? '' : `${GLYPH[name]} `

/** Pet costume -> glyph. */
export const costumeGlyph = (c: 'detective' | 'scientist' | 'planner' | 'scribe' | 'builder' | 'plain'): string => GLYPH[c]
